"""minimal cpylog stub for offline regression testing"""
import sys

class SimpleLogger:
    def __init__(self, level='debug', encoding='utf-8', log_func=None):
        self.level = level
        self.encoding = encoding
        self._quiet = level in ('warning', 'error', 'critical')

    def properties(self):
        return 0, ''

    def _write(self, kind, msg):
        if self._quiet and kind in ('debug', 'info'):
            return
        sys.stdout.write('%s: %s\n' % (kind.upper(), msg))

    def debug(self, msg):
        self._write('debug', msg)
    def info(self, msg):
        self._write('info', msg)
    def warning(self, msg):
        self._write('warning', msg)
    def error(self, msg):
        self._write('error', msg)
    def critical(self, msg):
        self._write('critical', msg)
    def exception(self, msg):
        self._write('error', msg)


def get_logger(log=None, level='debug', encoding='utf-8'):
    if log is not None:
        return log
    return SimpleLogger(level=level, encoding=encoding)


def get_logger2(log=None, debug=True, encoding='utf-8'):
    if log is not None:
        return log
    level = 'debug' if debug else ('warning' if debug is False else 'critical')
    return SimpleLogger(level=level, encoding=encoding)


